package com.amit.colortodo;
import android.app.*;import android.appwidget.*;import android.content.*;import android.net.Uri;import android.widget.*;
public class TodoWidget extends AppWidgetProvider {
 static final String TOGGLE="com.amit.colortodo.TOGGLE_TASK",EXTRA_ID="task_id",EXTRA_WIDGET="widget_id";
 @Override public void onUpdate(Context c,AppWidgetManager m,int[] ids){for(int id:ids)update(c,m,id);}
 @Override public void onReceive(Context c,Intent i){super.onReceive(c,i);if(TOGGLE.equals(i.getAction())){long id=i.getLongExtra(EXTRA_ID,-1);if(id<0)return;java.util.ArrayList<TaskStore.Task> ts=TaskStore.load(c);boolean changed=false;for(TaskStore.Task t:ts)if(t.id==id){t.done=!t.done;changed=true;break;}if(changed){TaskStore.save(c,ts);AppWidgetManager m=AppWidgetManager.getInstance(c);ComponentName n=new ComponentName(c,TodoWidget.class);m.notifyAppWidgetViewDataChanged(m.getAppWidgetIds(n),R.id.widgetStack);}}}
 static void refresh(Context c){AppWidgetManager m=AppWidgetManager.getInstance(c);ComponentName n=new ComponentName(c,TodoWidget.class);int[] ids=m.getAppWidgetIds(n);for(int id:ids){m.notifyAppWidgetViewDataChanged(id,R.id.widgetStack);update(c,m,id);}}
 static void update(Context c,AppWidgetManager m,int wid){RemoteViews v=new RemoteViews(c.getPackageName(),R.layout.widget_todo);Intent service=new Intent(c,TodoWidgetService.class);service.putExtra(AppWidgetManager.EXTRA_APPWIDGET_ID,wid);service.setData(Uri.parse(service.toUri(Intent.URI_INTENT_SCHEME)));v.setRemoteAdapter(R.id.widgetStack,service);v.setEmptyView(R.id.widgetStack,R.id.widgetEmpty);Intent template=new Intent(c,TodoWidget.class).setAction(TOGGLE);template.putExtra(EXTRA_WIDGET,wid);PendingIntent pi=PendingIntent.getBroadcast(c,wid,template,PendingIntent.FLAG_UPDATE_CURRENT|PendingIntent.FLAG_MUTABLE);v.setPendingIntentTemplate(R.id.widgetStack,pi);Intent open=new Intent(c,MainActivity.class);v.setOnClickPendingIntent(R.id.widgetTitle,PendingIntent.getActivity(c,9000+wid,open,PendingIntent.FLAG_UPDATE_CURRENT|PendingIntent.FLAG_IMMUTABLE));m.updateAppWidget(wid,v);}
}